def find_arithmetic_sequence(N, a):
    # Sort the sequence to find the common difference easily
    a_sorted = sorted(a)
    # Check if the sequence is already arithmetic
    if a == a_sorted:
        return a_sorted
    # Try to find the position where the sequence is not arithmetic
    for i in range(N):
        if a[i] != a_sorted[i]:
            # Replace the element at this position with the corresponding element in the sorted sequence
            return a[:i] + [a_sorted[i]] + a[i+1:]

def main():
    T = int(input())
    for _ in range(T):
        N = int(input())
        a = list(map(int, input().split()))
        result = find_arithmetic_sequence(N, a)
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
